export function circleBranch(run,scene) {
  if(!scene.index)return scene;
  const root=run.storyFlags[`choice:circle-${scene.line.key}-0`],plan=PLANS[scene.line.key]?.[root];
  if(!plan) {
    return {...scene,title:'重新说清以后 · '+scene.title,text:'上次的提议让人不舒服，这一章先从它留下的影响开始。两人都愿意重谈，但并没有把之前的失望当作已经消失。\n\n'+scene.text,branches:[['承认上次没有听完，先请对方说现在想要什么','你没有替任何人宣布和好。两人各说了一件希望改变的具体做法，之后的安排需要重新确认。'],['坦白自己也需要一点距离，暂时减少共同安排','你们同意不立即恢复原来的频率。关系没有被一个道歉按钮复原，之后还可以在愿意时接续。'],scene.branches[2]]};
  }
  const later=scene.index===2,offset=later?4:0;
  const priorChoice=run.storyFlags[`choice:circle-${scene.line.key}-1`];
  const continuity=later?priorChoice===2?'上一章两边都没能放心接受提议，所以这一次仍先谈尚未解决的期待。\n\n':`上一章真正采用的是「${run.storybook?.findLast(x=>x.id===`circle-${scene.line.key}-1`)?.options?.[priorChoice] || '当时共同选择的安排'}」。\n\n`:'';
  return {...scene,title:plan[offset],text:continuity+plan[offset+1],branches:later?[
    ['先把这次经历完整留下，再商量下一次','你们把实际发生的事分别说完，没有把另一种可能写成已经经历。接下来的邀请从这一次留下的细节开始。'],
    ['先回应眼前的邀请，把纪念留到之后','今晚先做彼此现在愿意做的那件小事。没有整理完的记录仍在，也没有人替其他人决定必须何时完成。'],
    ['同时承诺所有安排，不留调整的时间','承诺写得很满，两人却指出还有现实安排没有确认。这一章结束时，分歧仍留在记录里。'],
  ]:[
    [plan[2],'你们选择了这条安排，另一种做法留到以后再谈。真正采用的方案会成为下一章的起点。'],
    [plan[3],'你们选择了另一条同样可行的安排，也说明这次暂时不做什么。之后会从这个不同的经历接续。'],
    ['两种安排都先答应，之后再想办法','你们没有立即得到双倍的相处。两人希望先确定今晚究竟能做到什么，计划仍然需要重谈。'],
  ]};
}
